"""Task-only policy selection; original official scoring remains external."""
from v9_tasks_aff216cf6ffc.two5.policy import make_policy_b as make_two5
from v9_tasks_aff216cf6ffc.two10.policy import make_policy_b as make_two10

class TaskOnlyPolicy:
    action_mode='cartesian_delta'
    name='v9_task_specific_visual_force_rules'
    def __init__(self):
        self.parents={'2x5':make_two5(),'2x10':make_two10()};self.active=None
    def reset(self,context):
        self.selected_parent='2x10' if '20 cookies' in context.task.lower() else '2x5'
        self.active=self.parents[self.selected_parent];self.active.reset(context)
    def act(self,observation,task=''):
        if self.active is None:raise RuntimeError('reset before act')
        return self.active.act(observation,task)
    def __getattr__(self,name):
        active=self.__dict__.get('active')
        if active is None:raise AttributeError(name)
        return getattr(active,name)
    @property
    def finished(self):return False if self.active is None else self.active.finished
    @property
    def phase_name(self):return 'UNINITIALIZED' if self.active is None else self.active.phase_name
    def close(self):
        for policy in self.parents.values():policy.close()

def make_policy_b():return TaskOnlyPolicy()
def make_policy():return TaskOnlyPolicy()

